// Zig command sample built against the generated C bindings.
//
// natcatty_v1.h supplies every wire constant, enum, host-service module and
// method id, including the guest export names published through @export below.
// natcatty_v1.c (generated by the same IDL) is compiled into this module by
// build.sh and binds the host calls to the wasm import table, because Zig's
// @cImport cannot carry clang's import_module/import_name attributes. The
// generated natcatty_guest_init (not reimplemented here) performs init-time
// ABI negotiation.
const c = @cImport({
    @cInclude("natcatty_v1.h");
});

const hello = "hello from zig";

// The host writes a command into this fixed scratch buffer because the sample
// has no allocator.
var scratch: [4096]u8 = undefined;

fn abiVersion() callconv(.c) c.natcatty_i32 {
    return c.NATCATTY_ABI_VERSION;
}

fn init() callconv(.c) c.natcatty_i32 {
    return c.natcatty_guest_init();
}

fn dispatch(commandPtr: c.natcatty_u32, commandLen: c.natcatty_u32) callconv(.c) c.natcatty_i32 {
    _ = commandPtr;
    _ = commandLen;
    const status = c.natcatty_host_output_write(
        @intCast(@intFromPtr(hello.ptr)),
        @intCast(hello.len),
    );
    if (status < 0) {
        return -1;
    }
    return 0;
}

fn scratchPointer() callconv(.c) c.natcatty_u32 {
    return @intCast(@intFromPtr(&scratch));
}

fn poll() callconv(.c) c.natcatty_i32 {
    return 0;
}

fn shutdown() callconv(.c) c.natcatty_i32 {
    return 0;
}

comptime {
    @export(&abiVersion, .{ .name = c.NATCATTY_WIRE_ABI_VERSION });
    @export(&init, .{ .name = c.NATCATTY_WIRE_INIT });
    @export(&dispatch, .{ .name = c.NATCATTY_WIRE_DISPATCH });
    @export(&scratchPointer, .{ .name = c.NATCATTY_WIRE_SCRATCH });
    @export(&poll, .{ .name = c.NATCATTY_WIRE_POLL });
    @export(&shutdown, .{ .name = c.NATCATTY_WIRE_SHUTDOWN });
}
